sys_script_fix.script:
(function() {
    var incidentGR = new GlideRecord('incident');
    incidentGR.query();
    var descriptionMap = {};

    while (incidentGR.next()) {
        var shortDesc = incidentGR.short_description;  

        if (descriptionMap[shortDesc]) {
            incidentGR.deleteRecord();
            gs.info('Deleted duplicate Incident with short_description: ' + shortDesc);
        } else {
            descriptionMap[shortDesc] = incidentGR.sys_id;
        }
    }
})();
